const g=new THREE.Group();
const mat=ctx.makeMat({color:'#4fd1c5',rough:0.4,emissive:'#0b3d3a'});
[35,60,85,110,135].forEach((deg,k)=>{
  const th=deg*Math.PI/180, pts=[];
  for(let i=0;i<48;i++){
    const a=2*Math.PI*i/48, r=1.62+0.18*Math.sin(5*a+k*1.3);
    pts.push(new THREE.Vector3(r*Math.sin(th)*Math.cos(a), r*Math.cos(th), r*Math.sin(th)*Math.sin(a)));
  }
  g.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts,true),160,0.07,8,true),mat));
});
return g;
